@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#071b2c;--panel:#0d2639;--panel2:#123349;--line:#24516a;--aqua:#63e4d3;--mint:#a1f2cf;--cream:#e9f5e8;--muted:#8caeb7;--gold:#ffd77c}*{box-sizing:border-box}body{margin:0;background:#061522;color:var(--cream);font-family:Manrope,system-ui,sans-serif;min-height:100vh;display:grid;place-items:center}.game-shell{width:min(1200px,100vw);height:min(820px,100vh);min-height:540px;background:var(--ink);display:flex;flex-direction:column;overflow:hidden;border:1px solid #16344a;box-shadow:0 24px 80px #020a10}.topbar{height:66px;flex-shrink:0;display:flex;align-items:center;padding:0 23px;background:#0a2031;border-bottom:1px solid #173b50;gap:26px;z-index:2}.brand{display:flex;gap:10px;align-items:center;text-decoration:none;color:#edfff3;font-size:16px;font-weight:800;letter-spacing:2px;line-height:1}.brand small{display:block;color:#81b7bb;font:9px 'DM Mono',monospace;letter-spacing:2.1px;margin-top:5px}.brand-mark{width:35px;height:35px;border-radius:12px;background:linear-gradient(145deg,#66dec7,#a2f1ce);display:grid;place-items:center;color:#0b4450;font-size:21px;box-shadow:0 0 18px #42c8bb44}.world-label{margin:auto;display:flex;align-items:center;gap:10px;font:10px 'DM Mono',monospace;letter-spacing:1px;color:#b8d5d4}.world-label i{color:#386373}.live-dot{height:7px;width:7px;background:#72ecc6;border-radius:50%;box-shadow:0 0 8px #72ecc6}.top-actions{display:flex;align-items:center;gap:13px}.coins{font:12px 'DM Mono',monospace;color:var(--gold);background:#263a3c;padding:9px 13px;border:1px solid #4b5c4b;border-radius:8px}.coins b{font-weight:500}.icon-btn,.avatar-btn{height:34px;width:36px;border:1px solid #285168;border-radius:9px;background:#102d40;color:#b4d7d2;font-size:17px;cursor:pointer}.avatar-btn{border-radius:50%;width:34px;background:#e6c691;color:#31493e;font-weight:800}.game-stage{position:relative;flex:1;min-height:0;overflow:hidden;background:#5bb7b5}#world{width:100%;height:100%;display:block;image-rendering:pixelated}.world-overlay{position:absolute;top:17px;left:20px;right:20px;display:flex;justify-content:space-between;pointer-events:none}.location-chip,.world-coords{font:10px 'DM Mono',monospace;letter-spacing:.7px;color:#f0fff2;background:#072435b8;border:1px solid #d5fff033;border-radius:7px;padding:9px 12px;backdrop-filter:blur(8px)}.location-chip>span:first-child{color:#70edcf;font-size:13px;margin-right:6px}.location-chip .chip-divider{display:inline-block;height:11px;border-left:1px solid #6b8f91;margin:0 9px -2px}.world-coords{color:#b9e8d8}.quest-card{position:absolute;top:68px;left:20px;width:244px;display:flex;align-items:center;gap:10px;background:#0c2639e8;border:1px solid #427078;border-radius:10px;padding:11px 12px;box-shadow:0 7px 20px #11364933}.quest-icon{width:30px;height:30px;border-radius:9px;background:#204b52;color:#a6f1c7;display:grid;place-items:center;font-size:17px}.quest-card div{flex:1}.quest-card small,.quest-card span{display:block;font:9px 'DM Mono',monospace;color:#89bbc0;letter-spacing:.5px}.quest-card strong{display:block;font-size:10px;margin:3px 0 4px;color:#e5f6e8}.quest-card span em{color:var(--gold);font-style:normal}.quest-card button{border:0;background:none;color:#90c7c1;font-size:19px;cursor:pointer}.quick-actions{position:absolute;right:16px;top:78px;display:flex;flex-direction:column;gap:7px}.quick-btn{width:52px;height:53px;border:1px solid #c1e6db77;border-radius:10px;background:#0a2b3bbd;color:#dcf6e8;display:grid;place-items:center;cursor:pointer;backdrop-filter:blur(5px)}.quick-btn span{font-size:20px;color:#9be5cb;line-height:1}.quick-btn small{font:8px 'DM Mono',monospace;letter-spacing:.5px}.quick-btn:hover,.icon-btn:hover,.bottom-nav button:hover{background:#1b4656}.toast{position:absolute;top:20px;left:50%;transform:translate(-50%,-20px);background:#092638ee;border:1px solid #61d9c5;border-radius:8px;padding:10px 18px;font:11px 'DM Mono',monospace;color:#d9fff0;opacity:0;transition:.25s;pointer-events:none;z-index:7}.toast.show{opacity:1;transform:translate(-50%,0)}.cast-status{position:absolute;bottom:115px;left:50%;transform:translateX(-50%);font:10px 'DM Mono',monospace;letter-spacing:1px;color:#f0fff2;text-shadow:0 2px 6px #123;pointer-events:none}.minigame{display:none;position:absolute;left:50%;bottom:123px;transform:translateX(-50%);width:min(370px,82vw);padding:13px 16px 10px;background:#092637ed;border:1px solid #4b998e;border-radius:11px;box-shadow:0 12px 30px #03222f66}.minigame.active{display:block}.mini-title{font:9px 'DM Mono',monospace;letter-spacing:1px;color:#b5e5d6;text-align:center;margin-bottom:12px}.tension-track{height:17px;background:#204353;border-radius:6px;position:relative;overflow:hidden;border:1px solid #527b7a}.sweet-zone{position:absolute;left:39%;width:24%;height:100%;background:#61dba85c;border-left:1px solid #94efb5;border-right:1px solid #94efb5}.fish-marker,.tension-marker{position:absolute;width:3px;top:0;height:100%;background:#ffe58a;box-shadow:0 0 7px #ffe58a;left:48%}.tension-marker{background:#eaffef;box-shadow:0 0 5px white;left:50%}.mini-meta{display:flex;justify-content:space-between;color:#91c7c0;font:9px 'DM Mono',monospace;margin-top:8px}.catch-card{display:none;position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);z-index:5;width:220px;padding:19px;text-align:center;background:#0c2b3aee;border:1px solid #94d9ba;border-radius:14px;box-shadow:0 0 0 999px #03162266,0 15px 50px #062335aa}.catch-card.active{display:block;animation:pop .25s ease-out}@keyframes pop{from{transform:translate(-50%,-45%) scale(.8);opacity:0}to{transform:translate(-50%,-50%) scale(1);opacity:1}}.catch-glow{font-size:24px;color:#ffdf8a;text-shadow:0 0 20px #ffcf52;margin-bottom:3px}.catch-card>small{font:9px 'DM Mono',monospace;color:#a0d4c5;letter-spacing:1.5px}.catch-card strong{display:block;font-size:20px;margin:6px 0 7px}.catch-card>div:nth-of-type(2){font:9px 'DM Mono',monospace;color:#a8e8d3}.catch-card>div:nth-of-type(2) i{font-style:normal;margin:0 5px;color:#6b9998}.catch-card button{margin-top:15px;width:100%;border:0;border-radius:7px;padding:10px;background:linear-gradient(90deg,#76e2c6,#b9f1bd);color:#103a40;font:10px 'DM Mono',monospace;cursor:pointer}.bottom-hud{position:absolute;bottom:12px;left:15px;right:15px;display:flex;align-items:end;gap:15px;pointer-events:none}.level-card,.hotbar,.tool-hints{pointer-events:auto}.level-card{display:flex;align-items:center;gap:9px;background:#092638e8;border:1px solid #426473;border-radius:10px;padding:9px 11px;width:173px;height:54px}.level-icon{width:34px;height:34px;border-radius:9px;background:#e7ca91;color:#395048;display:grid;place-items:center;font-weight:800}.level-info{flex:1}.level-info>div:first-child{display:flex;justify-content:space-between;align-items:center}.level-info b{font-size:11px}.level-info span{font:8px 'DM Mono',monospace;color:#91c6be}.level-info span i{font-style:normal;color:#f4d47c;margin-left:4px}.xp-track{height:4px;margin-top:7px;border-radius:5px;background:#31515c;overflow:hidden}.xp-track span{display:block;width:37%;height:100%;background:#80e7bd}.hotbar{margin:auto;display:flex;gap:5px;position:relative;padding-top:13px}.hotbar-label{position:absolute;top:0;left:2px;font:8px 'DM Mono',monospace;letter-spacing:1px;color:#d4ede0;text-shadow:0 1px 3px #153}.slot{position:relative;width:52px;height:55px;border-radius:8px;border:1px solid #b5d7ca88;background:#0b2b3be8;color:#e6f4e3;display:flex;flex-direction:column;align-items:center;justify-content:center;cursor:pointer}.slot.active{border-color:#f2d47d;box-shadow:0 0 0 1px #f2d47d55}.slot-art{font-size:21px;color:#a0e9ce;height:24px;line-height:24px}.rod-art{transform:rotate(-25deg);color:#f4d08b}.water-art{color:#75d8df}.coral-art{color:#f4a38d}.slot small{position:absolute;left:5px;top:3px;color:#9abcb8;font:8px 'DM Mono',monospace}.slot b{font:7px 'DM Mono',monospace;letter-spacing:.4px}.slot b i{font-style:normal;color:#f6d982}.tool-hints{display:flex;flex-direction:column;gap:4px;align-items:flex-end;color:#e5f5e7;font:8px 'DM Mono',monospace;text-shadow:0 1px 4px #123}.tool-hints kbd{font:8px 'DM Mono',monospace;border:1px solid #d3eee388;background:#0a2a3bad;border-radius:3px;padding:2px 4px;margin-right:2px}.bottom-nav{height:57px;flex-shrink:0;display:flex;justify-content:center;gap:8px;align-items:center;background:#0a2031;border-top:1px solid #173b50}.bottom-nav button{height:39px;min-width:88px;border:1px solid transparent;border-radius:8px;background:transparent;color:#9fbfc1;font:9px 'DM Mono',monospace;letter-spacing:.8px;cursor:pointer}.bottom-nav button span{font-size:16px;vertical-align:-2px;margin-right:7px;color:#9be2c7}.panel-scrim{display:none;position:absolute;inset:0;z-index:10;background:#03152199;align-items:center;justify-content:center;padding:18px}.panel-scrim.open{display:flex}.panel{position:relative;width:min(510px,96%);max-height:85%;overflow:auto;background:#0b2538;border:1px solid #376174;border-radius:14px;padding:25px;box-shadow:0 25px 90px #020c13aa}.panel-close{position:absolute;right:14px;top:10px;border:0;background:none;color:#b3d4d0;font-size:25px;cursor:pointer}.panel h2{margin:0;font-size:20px;letter-spacing:.4px}.panel .subhead{margin:5px 0 18px;font:10px 'DM Mono',monospace;color:#84b1b5;letter-spacing:.8px}.panel-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.info-card,.fish-row,.craft-row{background:#102f43;border:1px solid #234c60;border-radius:9px;padding:12px}.info-card b,.fish-row b{display:block;font-size:12px}.info-card small,.fish-row small{display:block;font:9px 'DM Mono',monospace;color:#92b9bb;margin-top:5px}.fish-row{display:flex;align-items:center;gap:10px;margin:7px 0}.fish-emoji{width:34px;height:34px;background:#21495a;border-radius:8px;display:grid;place-items:center;font-size:18px}.rarity{margin-left:auto;font:8px 'DM Mono',monospace;color:#81e0c3}.action-btn{border:0;border-radius:7px;background:linear-gradient(100deg,#67dbc4,#b0eebe);color:#103a40;padding:10px 14px;font:10px 'DM Mono',monospace;cursor:pointer}.craft-row{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:8px 0}.craft-row div{font-size:11px}.craft-row small{display:block;font:9px 'DM Mono',monospace;color:#8fb4b6;margin-top:4px}.build-banner{display:none;position:absolute;top:16px;left:50%;transform:translateX(-50%);background:#153d47ed;border:1px solid #89e0bc;padding:9px 12px;border-radius:8px;font:10px 'DM Mono',monospace;white-space:nowrap;box-shadow:0 5px 16px #0e3344}.build-banner.active{display:flex;gap:12px;align-items:center}.build-banner span{font-size:9px;color:#b3d6c6}.build-banner button{border:0;border-radius:5px;background:#b1eac4;color:#164044;padding:5px 8px;font:9px 'DM Mono',monospace;cursor:pointer}.mobile-controls{display:none}.game-stage.building{cursor:crosshair}
@media(max-width:720px){body{display:block}.game-shell{height:100dvh;min-height:500px;width:100%;border:0}.topbar{height:55px;padding:0 12px;gap:8px}.brand{font-size:13px;letter-spacing:1.5px}.brand-mark{height:31px;width:31px}.world-label{font-size:8px;gap:5px}.world-label span:last-child{display:none}.top-actions{gap:7px}.coins{padding:7px 8px;font-size:10px}.icon-btn{display:none}.game-stage{flex:1}.world-overlay{top:10px;left:10px;right:10px}.location-chip,.world-coords{font-size:8px;padding:7px}.quest-card{left:10px;top:53px;width:211px;padding:8px}.quest-card strong{font-size:9px}.quick-actions{right:9px;top:62px}.quick-btn{width:44px;height:45px}.bottom-hud{bottom:67px;left:9px;right:9px;justify-content:center}.level-card{display:none}.tool-hints{display:none}.hotbar{margin:auto}.slot{width:47px;height:50px}.bottom-nav{height:58px;gap:0;justify-content:space-around}.bottom-nav button{min-width:0;width:20%;font-size:8px}.bottom-nav button span{display:block;margin:0 auto 2px;font-size:15px}.mobile-controls{display:flex;position:absolute;bottom:130px;left:12px;right:12px;align-items:end;gap:8px;pointer-events:none}.mobile-controls button{pointer-events:auto;border:1px solid #d8f7db88;background:#092c3ac9;color:#efffed;border-radius:50%;height:47px;width:47px;font-size:16px;touch-action:none}.mobile-controls #left-control{margin-right:0}.mobile-controls #jump-control{margin-left:auto}.mobile-controls #action-control{height:57px;width:57px;border-radius:19px;background:#d7df9ed9;color:#263f3d;font:9px 'DM Mono',monospace}.cast-status{bottom:198px}.minigame{bottom:188px}.catch-card{width:210px}.panel{padding:23px 16px}.build-banner{top:10px;max-width:95vw;white-space:normal;font-size:9px}.build-banner span{display:none}.bottom-nav{position:relative}}
@media(max-height:620px) and (min-width:721px){.topbar{height:53px}.bottom-nav{height:46px}.quest-card{top:58px}.bottom-hud{bottom:8px}.quick-actions{top:64px}}

(() => {
  const canvas = document.querySelector('#world'), ctx = canvas.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const fishData = [
    {name:'Bluegill',rarity:'Common',emoji:'🐟',min:.3,max:1.8,value:9,habitat:'Freshwater shallows',bait:'Worm'},
    {name:'River Minnow',rarity:'Common',emoji:'🐠',min:.1,max:.6,value:5,habitat:'River edge',bait:'Worm'},
    {name:'Silver Perch',rarity:'Common',emoji:'🐟',min:.5,max:2.2,value:12,habitat:'Freshwater pond',bait:'Grub'},
    {name:'Small Carp',rarity:'Common',emoji:'🐠',min:.7,max:3.4,value:15,habitat:'Pond',bait:'Worm'},
    {name:'Catfish',rarity:'Uncommon',emoji:'🐡',min:1.2,max:8,value:26,habitat:'Deep freshwater',bait:'Grub'},
    {name:'Rainbow Trout',rarity:'Uncommon',emoji:'🐟',min:.8,max:5.5,value:34,habitat:'River',bait:'Minnow'},
    {name:'Golden Koi',rarity:'Rare',emoji:'🐠',min:1,max:4,value:95,habitat:'Lily pond',bait:'Worm'},
    {name:'Crystal Perch',rarity:'Rare',emoji:'🐟',min:.7,max:3,value:120,habitat:'Crystal habitat',bait:'Glow lure'},
    {name:'Shadow Bass',rarity:'Epic',emoji:'🐡',min:2,max:11,value:240,habitat:'Night waters',bait:'Minnow'},
    {name:'Ancient Dragonfish',rarity:'Legendary',emoji:'🐉',min:8,max:28,value:850,habitat:'Hidden deep',bait:'Special'}
  ];
  const defaults = {coins:120, catches:[], inventory:{worm:8,water:24,coral:8}, world:{}, xp:0, level:3};
  let saved; try { saved = JSON.parse(localStorage.getItem('aquaria-save') || 'null'); } catch { saved = null; }
  const state = Object.assign({}, defaults, saved || {}); state.inventory = Object.assign({},defaults.inventory,state.inventory||{}); state.world = state.world || {};
  const player = {x:370,y:0,vy:0,grounded:false,facing:1,walk:0};
  let w=0,h=0,scale=1,camera=0,keys={},last=0,toastTimer, selected='rod', buildMode=false, panelOpen=false;
  let fishing={mode:'idle',timer:0,bobX:0,bobY:0,target:50,marker:50,progress:0,tension:40,fish:null};
  let dayClock=0, fishCaught=false, mobileMove=0;
  const tile=36, groundRatio=.73;
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  function save(){ localStorage.setItem('aquaria-save',JSON.stringify(state)); $('#coin-count').textContent=state.coins; $('#bait-count').textContent=state.inventory.worm; $('#water-count').textContent=state.inventory.water; $('#coral-count').textContent=state.inventory.coral; $('#quest-progress').textContent=state.catches.length?'1 / 1':'0 / 1'; $('#xp-bar').style.width=`${Math.min(100,20+state.xp%100)}%`; }
  function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
  function resize(){const r=canvas.getBoundingClientRect();const d=Math.min(devicePixelRatio||1,2);w=r.width;h=r.height;canvas.width=Math.floor(w*d);canvas.height=Math.floor(h*d);ctx.setTransform(d,0,0,d,0,0);if(!player.y)player.y=h*groundRatio-30;}
  new ResizeObserver(resize).observe(canvas); resize();
  function hash(n){let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)}
  function groundY(x){return h*groundRatio + Math.sin(x*.007)*4 + Math.sin(x*.021)*2}
  function worldWaterStart(){return 465}
  function screen(x){return x-camera}
  function drawBackground(t){
    const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#83d9cd');sky.addColorStop(.58,'#b5e4ce');sky.addColorStop(1,'#e1e6bf');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
    // soft sun and distant islands
    ctx.fillStyle='#fff0b977';ctx.beginPath();ctx.arc(w*.79,h*.2,42,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f9efc48c';ctx.beginPath();ctx.arc(w*.79,h*.2,28,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#6eb6a6';ctx.beginPath();ctx.moveTo(0,h*.53);for(let x=0;x<=w+10;x+=12)ctx.lineTo(x,h*.38+Math.sin((x+camera*.12)*.009)*23+Math.sin(x*.02)*9);ctx.lineTo(w,h*.78);ctx.lineTo(0,h*.78);ctx.fill();
    ctx.fillStyle='#90c9a9';ctx.beginPath();ctx.moveTo(0,h*.6);for(let x=0;x<=w+10;x+=12)ctx.lineTo(x,h*.46+Math.sin((x+camera*.19)*.012+1)*20);ctx.lineTo(w,h*.78);ctx.lineTo(0,h*.78);ctx.fill();
    for(let i=0;i<5;i++){let cx=(i*213-camera*.24)%(w+180);if(cx< -100)cx+=w+180;let cy=35+hash(i+3)*85;ctx.fillStyle='#f5fff0a8';ctx.beginPath();ctx.ellipse(cx,cy,30,7,0,0,Math.PI*2);ctx.ellipse(cx+22,cy-3,20,8,0,0,Math.PI*2);ctx.ellipse(cx-20,cy,17,6,0,0,Math.PI*2);ctx.fill()}
  }
  function drawEnvironment(t){
    const waterX=screen(worldWaterStart()), shoreY=groundY(worldWaterStart());
    // water mass and layered animated surface
    const water=ctx.createLinearGradient(0,shoreY,0,h);water.addColorStop(0,'#47c5be');water.addColorStop(.22,'#259dac');water.addColorStop(.67,'#176c89');water.addColorStop(1,'#104968');ctx.fillStyle=water;ctx.fillRect(Math.max(0,waterX),shoreY,w-Math.max(0,waterX),h-shoreY);
    if(waterX<0)ctx.fillRect(0,shoreY,Math.min(w,-waterX),h-shoreY);
    ctx.save();ctx.beginPath();ctx.rect(Math.max(0,waterX),shoreY,w,h-shoreY);ctx.clip();
    for(let i=0;i<12;i++){let x=((i*106+t*.018-camera*.2)%(w+100));if(x<0)x+=w+100;let y=shoreY+12+((i*37)%Math.max(30,h-shoreY-25));ctx.fillStyle=i%2?'#b8f5d01a':'#d9fff42b';ctx.fillRect(x,y,30+hash(i)*28,2)}
    // distant underwater light shafts
    for(let i=0;i<5;i++){let x=waterX+80+i*105+t*.003;ctx.fillStyle='#afffea0b';ctx.beginPath();ctx.moveTo(x,shoreY);ctx.lineTo(x+42,shoreY);ctx.lineTo(x-15,h);ctx.lineTo(x-55,h);ctx.fill()}
    // underwater rocks and fronds
    for(let i=0;i<16;i++){let wx=worldWaterStart()+30+i*88;if(wx<camera-100||wx>camera+w+100)continue;let x=screen(wx),by=groundY(wx)+95+hash(i)*48;ctx.fillStyle=i%2?'#286f73':'#276479';ctx.beginPath();ctx.ellipse(x,by,18+hash(i+9)*12,9,0,0,Math.PI*2);ctx.fill();if(i%3!==1)drawPlant(x+8,by-3,hash(i+4),t)}
    // swimming ambient fish
    for(let i=0;i<7;i++){let x=(i*155+t*(.015+i*.003)-camera*.1)%(w+80);if(x<0)x+=w+80;let y=shoreY+45+(i*59)%(Math.max(60,h-shoreY-70));drawFishSprite(x,y, i%2?1:-1,.7+i%3*.15, i%2?'#b9ead0':'#edc985')}
    // bubbles
    for(let i=0;i<9;i++){let x=((i*91+t*.012-camera*.23)%(w+20));if(x<0)x+=w+20;let y=shoreY+18+((i*61-t*.018)%(h-shoreY-25)+h-shoreY-25)%(h-shoreY-25);ctx.strokeStyle='#dbfff277';ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y,2+i%3,0,Math.PI*2);ctx.stroke()}
    ctx.restore();
    // grass and dirt ground, draw land until water edge
    ctx.fillStyle='#7dbb77';ctx.beginPath();ctx.moveTo(0,groundY(camera));for(let sx=0;sx<=Math.min(w,waterX);sx+=12)ctx.lineTo(sx,groundY(camera+sx));ctx.lineTo(Math.min(w,waterX),h);ctx.lineTo(0,h);ctx.fill();
    ctx.fillStyle='#866a4f';ctx.beginPath();ctx.moveTo(0,h*.79);ctx.lineTo(Math.min(w,waterX),h*.79);for(let sx=Math.min(w,waterX);sx>=0;sx-=12)ctx.lineTo(sx,groundY(camera+sx)+28);ctx.closePath();ctx.fill();
    // grass ledge
    for(let sx=0;sx<Math.min(w,waterX);sx+=12){let wx=camera+sx, gy=groundY(wx);ctx.fillStyle=hash(Math.floor(wx/12))>.5?'#9acb7b':'#83bf72';ctx.fillRect(sx,gy-2,12,5);if(hash(Math.floor(wx/19)+31)>.78){ctx.fillStyle='#d5d982';ctx.fillRect(sx+5,gy-8,2,6);ctx.fillStyle='#f1c7a0';ctx.fillRect(sx+3,gy-10,6,4)}}
    // low-poly shore shelf / foam
    ctx.fillStyle='#d1d58f';ctx.fillRect(Math.max(0,waterX-5),shoreY-1,Math.min(10,w-waterX+5),5);ctx.fillStyle='#eff0bf';ctx.fillRect(Math.max(0,waterX-4),shoreY-2,5,2);
    // trees, shrubs, rocks
